R["apx-m6-secondmax"] = "public class Solution {\n    public static int process(int[] arr) {\n        if (arr.length < 2) {\n            return -1;\n        }\n        int max = arr[0];\n        for (int v : arr) {\n            if (v > max) {\n                max = v;\n            }\n        }\n        int second = Integer.MIN_VALUE;\n        for (int v : arr) {\n            if (v < max && v > second) {\n                second = v;\n            }\n        }\n        return second == Integer.MIN_VALUE ? -1 : second;\n    }\n}\n";
W["apx-m6-secondmax"] = "public class Solution {\n    // BUG: single-pass branch misses equal-to-max \u2014 counts duplicates of max as second\n    public static int process(int[] arr) {\n        if (arr.length < 2) {\n            return -1;\n        }\n        int max = Integer.MIN_VALUE;\n        int second = Integer.MIN_VALUE;\n        for (int v : arr) {\n            if (v > max) {\n                second = max;\n                max = v;\n            } else if (v > second) {\n                second = v;\n            }\n        }\n        return second == Integer.MIN_VALUE ? -1 : second;\n    }\n}\n";
R["apx-m6-rotate"] = "public class Solution {\n    public static void rotate(int[] arr, int k) {\n        int n = arr.length;\n        if (n == 0) {\n            return;\n        }\n        k = k % n;\n        int[] tmp = new int[n];\n        for (int i = 0; i < n; i++) {\n            tmp[(i + k) % n] = arr[i];\n        }\n        for (int i = 0; i < n; i++) {\n            arr[i] = tmp[i];\n        }\n    }\n}\n";
W["apx-m6-rotate"] = "public class Solution {\n    // BUG: rotates LEFT instead of right (tmp[(i - k + n) % n])\n    public static void rotate(int[] arr, int k) {\n        int n = arr.length;\n        if (n == 0) {\n            return;\n        }\n        k = k % n;\n        int[] tmp = new int[n];\n        for (int i = 0; i < n; i++) {\n            tmp[((i - k) % n + n) % n] = arr[i];\n        }\n        for (int i = 0; i < n; i++) {\n            arr[i] = tmp[i];\n        }\n    }\n}\n";
R["apx-m6-mode"] = "public class Solution {\n    public static int process(java.util.ArrayList<Integer> list) {\n        int bestVal = 0;\n        int bestCount = 0;\n        for (int i = 0; i < list.size(); i++) {\n            int v = list.get(i);\n            int cnt = 0;\n            for (int j = 0; j < list.size(); j++) {\n                if (list.get(j).equals(v)) {\n                    cnt++;\n                }\n            }\n            if (cnt > bestCount || (cnt == bestCount && v < bestVal)) {\n                bestCount = cnt;\n                bestVal = v;\n            }\n        }\n        return bestVal;\n    }\n}\n";
