R["apx-m7-neighborsum"] = "public class Solution {\n    public static int process(int[][] g, int r, int c) {\n        int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};\n        int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};\n        int sum = 0;\n        for (int d = 0; d < 8; d++) {\n            int nr = r + dr[d];\n            int nc = c + dc[d];\n            if (nr >= 0 && nr < g.length && nc >= 0 && nc < g[0].length) {\n                sum += g[nr][nc];\n            }\n        }\n        return sum;\n    }\n}\n";
W["apx-m7-neighborsum"] = "public class Solution {\n    // BUG: includes the cell itself \u2014 self counts as a neighbor\n    public static int process(int[][] g, int r, int c) {\n        int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};\n        int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};\n        int sum = 0;\n        for (int d = 0; d < 8; d++) {\n            int nr = r + dr[d];\n            int nc = c + dc[d];\n            if (nr >= 0 && nr < g.length && nc >= 0 && nc < g[0].length) {\n                sum += g[nr][nc];\n            }\n        }\n        return sum + g[r][c];\n    }\n}\n";
R["apx-m7-peaks"] = "public class Solution {\n    public static int process(int[][] g) {\n        int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};\n        int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};\n        int count = 0;\n        for (int r = 0; r < g.length; r++) {\n            for (int c = 0; c < g[0].length; c++) {\n                int sum = 0;\n                int cnt = 0;\n                for (int d = 0; d < 8; d++) {\n                    int nr = r + dr[d];\n                    int nc = c + dc[d];\n                    if (nr >= 0 && nr < g.length && nc >= 0 && nc < g[0].length) {\n                        sum += g[nr][nc];\n                        cnt++;\n                    }\n                }\n                if (g[r][c] * cnt > sum) {\n                    count++;\n                }\n            }\n        }\n        return count;\n    }\n}\n";
W["apx-m7-peaks"] = "public class Solution {\n    // BUG: divides by 8 always \u2014 corners and edges misjudged\n    public static int process(int[][] g) {\n        int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};\n        int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};\n        int count = 0;\n        for (int r = 0; r < g.length; r++) {\n            for (int c = 0; c < g[0].length; c++) {\n                int sum = 0;\n                for (int d = 0; d < 8; d++) {\n                    int nr = r + dr[d];\n                    int nc = c + dc[d];\n                    if (nr >= 0 && nr < g.length && nc >= 0 && nc < g[0].length) {\n                        sum += g[nr][nc];\n                    }\n                }\n                if (g[r][c] * 8 > sum) {\n                    count++;\n                }\n            }\n        }\n        return count;\n    }\n}\n";
R["apx-m7-ledger"] = "public class Solution {\n    public static int process(int[][] g) {\n        int total = 0;\n        for (int c = 0; c < g[0].length; c++) {\n            int col = 0;\n            for (int r = 0; r < g.length; r++) {\n                col += g[r][c];\n            }\n            total += Math.abs(col);\n        }\n        return total;\n    }\n}\n";
