R["apx-m7-spiral"] = "public class Solution {\n    public static int[][] fill(int rows, int cols) {\n        int[][] g = new int[rows][cols];\n        int v = 1;\n        int top = 0;\n        int bottom = rows - 1;\n        int left = 0;\n        int right = cols - 1;\n        while (top <= bottom && left <= right) {\n            for (int c = left; c <= right; c++) {\n                g[top][c] = v;\n                v++;\n            }\n            top++;\n            for (int r = top; r <= bottom; r++) {\n                g[r][right] = v;\n                v++;\n            }\n            right--;\n            if (top <= bottom) {\n                for (int c = right; c >= left; c--) {\n                    g[bottom][c] = v;\n                    v++;\n                }\n                bottom--;\n            }\n            if (left <= right) {\n                for (int r = bottom; r >= top; r--) {\n                    g[r][left] = v;\n                    v++;\n                }\n                left++;\n            }\n        }\n        return g;\n    }\n}\n";
W["apx-m7-spiral"] = "public class Solution {\n    // BUG: missing the re-check before the bottom row \u2014 single-column grids double-count\n    public static int[][] fill(int rows, int cols) {\n        int[][] g = new int[rows][cols];\n        int v = 1;\n        int top = 0;\n        int bottom = rows - 1;\n        int left = 0;\n        int right = cols - 1;\n        while (top <= bottom && left <= right) {\n            for (int c = left; c <= right; c++) {\n                g[top][c] = v;\n                v++;\n            }\n            top++;\n            for (int r = top; r <= bottom; r++) {\n                g[r][right] = v;\n                v++;\n            }\n            right--;\n            for (int c = right; c >= left; c--) {\n                g[bottom][c] = v;\n                v++;\n            }\n            bottom--;\n            if (left <= right) {\n                for (int r = bottom; r >= top; r--) {\n                    g[r][left] = v;\n                    v++;\n                }\n                left++;\n            }\n        }\n        return g;\n    }\n}\n";
R["apx-cp-m7-symmetric"] = "public class Solution {\n    public static boolean process(int[][] g) {\n        for (int r = 0; r < g.length; r++) {\n            for (int c = r + 1; c < g.length; c++) {\n                if (g[r][c] != g[c][r]) {\n                    return false;\n                }\n            }\n        }\n        return true;\n    }\n}\n";
W["apx-cp-m7-symmetric"] = "public class Solution {\n    // BUG: compares against the wrong mirror index (c - r instead of c, r)\n    public static boolean process(int[][] g) {\n        for (int r = 0; r < g.length; r++) {\n            for (int c = r + 1; c < g.length; c++) {\n                if (g[r][c] != g[c - r][r]) {\n                    return false;\n                }\n            }\n        }\n        return true;\n    }\n}\n";
R["apx-m8-parking"] = "public class Solution {\n    public static class Parking {\n        private int capacity;\n        private java.util.ArrayList<String> plates = new java.util.ArrayList<String>();\n\n        public Parking(int capacity) {\n            this.capacity = capacity;\n        }\n\n        public boolean arrive(String plate) {\n            if (plates.size() >= capacity) {\n                return false;\n            }\n            plates.add(plate);\n            return true;\n        }\n\n        public boolean depart(String plate) {\n            return plates.remove(plate);\n        }\n\n        public int count() {\n            return plates.size();\n        }\n    }\n}\n";
W["apx-m8-parking"] = "public class Solution {\n    public static class Parking {\n        private int capacity;\n        private java.util.ArrayList<String> plates = new java.util.ArrayList<String>();\n\n        public Parking(int capacity) {\n            this.capacity = capacity;\n        }\n\n        public boolean arrive(String plate) {\n            if (plates.size() >= capacity) {\n                return false;\n            }\n            plates.add(plate);\n            return true;\n        }\n\n        public boolean depart(String plate) {\n            // BUG: removes by INDEX semantics confusion \u2014 removes first element instead\n            if (plates.size() > 0) {\n                plates.remove(0);\n                return true;\n            }\n            return false;\n        }\n\n        public int count() {\n            return plates.size();\n        }\n    }\n}\n";
