R["apx-m10-stairs"] = "public class Solution {\n    public static int process(int n) {\n        if (n <= 1) {\n            return 1;\n        }\n        return process(n - 1) + process(n - 2);\n    }\n}\n";
W["apx-m10-stairs"] = "public class Solution {\n    // BUG: base case returns 0 for n == 0 \u2014 shifts the whole sequence\n    public static int process(int n) {\n        if (n == 1) {\n            return 1;\n        }\n        if (n == 0) {\n            return 0;\n        }\n        return process(n - 1) + process(n - 2);\n    }\n}\n";
R["apx-m10-reverse"] = "public class Solution {\n    public static String process(String s) {\n        if (s.length() <= 1) {\n            return s;\n        }\n        return process(s.substring(1)) + s.charAt(0);\n    }\n}\n";
