R["apx-m10-subsetsum"] = "public class Solution {\n    public static boolean hasSum(int[] arr, int target) {\n        return tryFrom(arr, 0, target);\n    }\n\n    private static boolean tryFrom(int[] arr, int i, int target) {\n        if (i == arr.length) {\n            return target == 0;\n        }\n        return tryFrom(arr, i + 1, target - arr[i]) || tryFrom(arr, i + 1, target);\n    }\n}\n";
W["apx-m10-subsetsum"] = "public class Solution {\n    public static boolean hasSum(int[] arr, int target) {\n        return tryFrom(arr, 0, target);\n    }\n\n    private static boolean tryFrom(int[] arr, int i, int target) {\n        if (i == arr.length) {\n            return target == 0;\n        }\n        // BUG: only the include branch \u2014 skips valid excluded sums\n        return tryFrom(arr, i + 1, target - arr[i]);\n    }\n}\n";
R["apx-m10-gcd"] = "public class Solution {\n    public static int gcd(int a, int b) {\n        if (b == 0) {\n            return a;\n        }\n        return gcd(b, a % b);\n    }\n}\n";
W["apx-m10-gcd"] = "public class Solution {\n    // BUG: swapped arguments in the recursion \u2014 gcd(b % a, b) can loop\n    public static int gcd(int a, int b) {\n        if (b == 0) {\n            return a;\n        }\n        return gcd(b % a, b);\n    }\n}\n";
R["apx-cp-m10-digitsum"] = "public class Solution {\n    public static int process(int n) {\n        if (n < 10) {\n            return n;\n        }\n        return process(digitSum(n));\n    }\n\n    private static int digitSum(int n) {\n        if (n == 0) {\n            return 0;\n        }\n        return n % 10 + digitSum(n / 10);\n    }\n}\n";
W["apx-cp-m10-digitsum"] = "public class Solution {\n    public static int process(int n) {\n        if (n < 10) {\n            return n;\n        }\n        // BUG: one digit-sum pass only \u2014 never recurses on the result\n        return digitSum(n);\n    }\n\n    private static int digitSum(int n) {\n        if (n == 0) {\n            return 0;\n        }\n        return n % 10 + digitSum(n / 10);\n    }\n}\n";
R["apx-m11-vowelstep"] = "public class Solution {\n    public static String encode(String word) {\n        StringBuilder out = new StringBuilder();\n        for (int i = 0; i < word.length(); i++) {\n            char ch = word.charAt(i);\n            if (\"aeiou\".indexOf(ch) >= 0) {\n                ch = (char) (ch + 1);\n            }\n            out.append(ch);\n        }\n        return out.toString();\n    }\n}\n";
W["apx-m11-vowelstep"] = "public class Solution {\n    // BUG: shifts vowels by two \u2014 misread \"next\" as \"after next\"\n    public static String encode(String word) {\n        StringBuilder out = new StringBuilder();\n        for (int i = 0; i < word.length(); i++) {\n            char ch = word.charAt(i);\n            if (\"aeiou\".indexOf(ch) >= 0) {\n                ch = (char) (ch + 2);\n            }\n            out.append(ch);\n        }\n        return out.toString();\n    }\n}\n";
R["apx-m11-altitude"] = "public class Solution {\n    public static int process(java.util.ArrayList<String> log) {\n        int altitude = 0;\n        for (String s : log) {\n            for (int i = 0; i < s.length(); i++) {\n                char ch = s.charAt(i);\n                if (ch == 'U') {\n                    altitude++;\n                } else if (ch == 'D') {\n                    altitude--;\n                }\n            }\n        }\n        return altitude;\n    }\n}\n";
W["apx-m11-altitude"] = "public class Solution {\n    // BUG: resets the accumulator for every string \u2014 loses earlier entries\n    public static int process(java.util.ArrayList<String> log) {\n        int total = 0;\n        for (String s : log) {\n            int altitude = 0;\n            for (int i = 0; i < s.length(); i++) {\n                char ch = s.charAt(i);\n                if (ch == 'U') {\n                    altitude++;\n                } else if (ch == 'D') {\n                    altitude--;\n                }\n            }\n            total = altitude;\n        }\n        return total;\n    }\n}\n";
R["apx-m11-dominant"] = "public class Solution {\n    public static int process(java.util.ArrayList<int[]> rows) {\n        int count = 0;\n        for (int[] row : rows) {\n            int max = Integer.MIN_VALUE;\n            int total = 0;\n            for (int v : row) {\n                total += v;\n                if (v > max) {\n                    max = v;\n                }\n            }\n            if (max > total - max) {\n                count++;\n            }\n        }\n        return count;\n    }\n}\n";
W["apx-m11-dominant"] = "public class Solution {\n    // BUG: compares max against the FULL total including itself\n    public static int process(java.util.ArrayList<int[]> rows) {\n        int count = 0;\n        for (int[] row : rows) {\n            int max = Integer.MIN_VALUE;\n            int total = 0;\n            for (int v : row) {\n                total += v;\n                if (v > max) {\n                    max = v;\n                }\n            }\n            if (max > total) {\n                count++;\n            }\n        }\n        return count;\n    }\n}\n";
