R["apx-m12-streak"] = "public class Solution {\n    public static int longestWarmStreak(double[] readings) {\n        int best = 0;\n        int cur = 0;\n        for (double v : readings) {\n            if (v > 15.0) {\n                cur++;\n                if (cur > best) {\n                    best = cur;\n                }\n            } else {\n                cur = 0;\n            }\n        }\n        return best;\n    }\n}\n";
W["apx-m12-streak"] = "public class Solution {\n    // BUG: never resets the run counter \u2014 streaks from earlier runs accumulate\n    public static int longestWarmStreak(double[] readings) {\n        int best = 0;\n        int cur = 0;\n        for (double v : readings) {\n            if (v > 15.0) {\n                cur++;\n                if (cur > best) {\n                    best = cur;\n                }\n            }\n        }\n        return best;\n    }\n}\n";
R["apx-m12-average"] = "public class Solution {\n    public static double averageForDay(String[] days, double[] temps, String day) {\n        double sum = 0.0;\n        int n = 0;\n        for (int i = 0; i < days.length; i++) {\n            if (days[i].equals(day)) {\n                sum += temps[i];\n                n++;\n            }\n        }\n        if (n == 0) {\n            return 0.0;\n        }\n        return sum / n;\n    }\n}\n";
W["apx-m12-average"] = "public class Solution {\n    // BUG: divides even when nothing matched \u2014 NaN for a missing day\n    public static double averageForDay(String[] days, double[] temps, String day) {\n        double sum = 0.0;\n        int n = 0;\n        for (int i = 0; i < days.length; i++) {\n            if (days[i].equals(day)) {\n                sum += temps[i];\n                n++;\n            }\n        }\n        return sum / n;\n    }\n}\n";
R["apx-cp-m12-fullfrq"] = "public class Solution {\n    public static class WarmWeek {\n        private double[] readings;\n\n        public WarmWeek(double[] readings) {\n            this.readings = readings;\n        }\n\n        public int coldHours() {\n            int count = 0;\n            for (double v : readings) {\n                if (v < 0.0) {\n                    count++;\n                }\n            }\n            return count;\n        }\n\n        public boolean hasWarmDay() {\n            for (double v : readings) {\n                if (v > 25.0) {\n                    return true;\n                }\n            }\n            return false;\n        }\n\n        public double firstBelow() {\n            for (double v : readings) {\n                if (v < 0.0) {\n                    return v;\n                }\n            }\n            return 999.0;\n        }\n    }\n}\n";
W["apx-cp-m12-fullfrq"] = "public class Solution {\n    public static class WarmWeek {\n        private double[] readings;\n\n        public WarmWeek(double[] readings) {\n            this.readings = readings;\n        }\n\n        public int coldHours() {\n            int count = 0;\n            for (double v : readings) {\n                if (v < 0.0) {\n                    count++;\n                }\n            }\n            return count;\n        }\n\n        public boolean hasWarmDay() {\n            // BUG: returns after checking only the FIRST element\n            if (readings.length > 0) {\n                return readings[0] > 25.0;\n            }\n            return false;\n        }\n\n        public double firstBelow() {\n            for (double v : readings) {\n                if (v < 0.0) {\n                    return v;\n                }\n            }\n            return 999.0;\n        }\n    }\n}\n";
R["apx-m13-frequent"] = "public class Solution {\n    public static char process(String s) {\n        char best = 0;\n        int bestN = 0;\n        for (int i = 0; i < s.length(); i++) {\n            char c = s.charAt(i);\n            int n = 0;\n            for (int j = 0; j < s.length(); j++) {\n                if (s.charAt(j) == c) {\n                    n++;\n                }\n            }\n            if (n > bestN || (n == bestN && c < best)) {\n                bestN = n;\n                best = c;\n            }\n        }\n        return best;\n    }\n}\n";
W["apx-m13-frequent"] = "public class Solution {\n    // BUG: on ties keeps the LAST seen instead of the alphabetically smallest\n    public static char process(String s) {\n        char best = 0;\n        int bestN = 0;\n        for (int i = 0; i < s.length(); i++) {\n            char c = s.charAt(i);\n            int n = 0;\n            for (int j = 0; j < s.length(); j++) {\n                if (s.charAt(j) == c) {\n                    n++;\n                }\n            }\n            if (n >= bestN) {\n                bestN = n;\n                best = c;\n            }\n        }\n        return best;\n    }\n}\n";
R["apx-m13-star"] = "public class Solution {\n    public static String process(String s) {\n        if (s.length() <= 1) {\n            return s;\n        }\n        StringBuilder out = new StringBuilder().append(s.charAt(0));\n        for (int i = 1; i < s.length(); i++) {\n            if (s.charAt(i) == s.charAt(i - 1)) {\n                out.append('*');\n            }\n            out.append(s.charAt(i));\n        }\n        return out.toString();\n    }\n}\n";
W["apx-m13-star"] = "public class Solution {\n    // BUG: appends the star AFTER the char \u2014 stars land in the wrong slots\n    public static String process(String s) {\n        if (s.length() <= 1) {\n            return s;\n        }\n        StringBuilder out = new StringBuilder();\n        for (int i = 0; i < s.length(); i++) {\n            out.append(s.charAt(i));\n            if (i + 1 < s.length() && s.charAt(i) == s.charAt(i + 1)) {\n                out.append('*');\n            }\n        }\n        return out.toString();\n    }\n}\n";
R["apx-m13-secondsmallest"] = "public class Solution {\n    public static int process(int[] arr) {\n        if (arr.length < 2) {\n            return -1;\n        }\n        int min = Integer.MAX_VALUE;\n        for (int v : arr) {\n            if (v < min) {\n                min = v;\n            }\n        }\n        int second = Integer.MAX_VALUE;\n        for (int v : arr) {\n            if (v > min && v < second) {\n                second = v;\n            }\n        }\n        return second == Integer.MAX_VALUE ? -1 : second;\n    }\n}\n";
W["apx-m13-secondsmallest"] = "public class Solution {\n    // BUG: accepts duplicates of the min as the \"second smallest\"\n    public static int process(int[] arr) {\n        if (arr.length < 2) {\n            return -1;\n        }\n        int min = Integer.MAX_VALUE;\n        for (int v : arr) {\n            if (v < min) {\n                min = v;\n            }\n        }\n        int second = Integer.MAX_VALUE;\n        for (int v : arr) {\n            if (v >= min && v < second) {\n                second = v;\n            }\n        }\n        return second == Integer.MAX_VALUE ? -1 : second;\n    }\n}\n";
