R["apx-m13-frequent"] = "public class Solution {\n    public static char process(String s) {\n        char best = 0;\n        int bestN = 0;\n        for (int i = 0; i < s.length(); i++) {\n            char c = s.charAt(i);\n            int n = 0;\n            for (int j = 0; j < s.length(); j++) {\n                if (s.charAt(j) == c) {\n                    n++;\n                }\n            }\n            if (n > bestN || (n == bestN && c < best)) {\n                bestN = n;\n                best = c;\n            }\n        }\n        return best;\n    }\n}\n";
W["apx-m13-frequent"] = "public class Solution {\n    // BUG: on ties keeps the LAST seen instead of the alphabetically smallest\n    public static char process(String s) {\n        char best = 0;\n        int bestN = 0;\n        for (int i = 0; i < s.length(); i++) {\n            char c = s.charAt(i);\n            int n = 0;\n            for (int j = 0; j < s.length(); j++) {\n                if (s.charAt(j) == c) {\n                    n++;\n                }\n            }\n            if (n >= bestN) {\n                bestN = n;\n                best = c;\n            }\n        }\n        return best;\n    }\n}\n";
R["apx-m13-star"] = "public class Solution {\n    public static String process(String s) {\n        if (s.length() <= 1) {\n            return s;\n        }\n        StringBuilder out = new StringBuilder().append(s.charAt(0));\n        for (int i = 1; i < s.length(); i++) {\n            if (s.charAt(i) == s.charAt(i - 1)) {\n                out.append('*');\n            }\n            out.append(s.charAt(i));\n        }\n        return out.toString();\n    }\n}\n";
W["apx-m13-star"] = "public class Solution {\n    // BUG: inserts at most ONE star \u2014 the flag latches after the first pair\n    public static String process(String s) {\n        if (s.length() <= 1) {\n            return s;\n        }\n        StringBuilder out = new StringBuilder().append(s.charAt(0));\n        boolean used = false;\n        for (int i = 1; i < s.length(); i++) {\n            if (!used && s.charAt(i) == s.charAt(i - 1)) {\n                out.append('*');\n                used = true;\n            }\n            out.append(s.charAt(i));\n        }\n        return out.toString();\n    }\n}\n";
R["apx-m13-secondsmallest"] = "public class Solution {\n    public static int process(int[] arr) {\n        if (arr.length < 2) {\n            return -1;\n        }\n        int min = Integer.MAX_VALUE;\n        for (int v : arr) {\n            if (v < min) {\n                min = v;\n            }\n        }\n        int second = Integer.MAX_VALUE;\n        for (int v : arr) {\n            if (v > min && v < second) {\n                second = v;\n            }\n        }\n        return second == Integer.MAX_VALUE ? -1 : second;\n    }\n}\n";
W["apx-m13-secondsmallest"] = "public class Solution {\n    // BUG: accepts duplicates of the min as the \"second smallest\"\n    public static int process(int[] arr) {\n        if (arr.length < 2) {\n            return -1;\n        }\n        int min = Integer.MAX_VALUE;\n        for (int v : arr) {\n            if (v < min) {\n                min = v;\n            }\n        }\n        int second = Integer.MAX_VALUE;\n        for (int v : arr) {\n            if (v >= min && v < second) {\n                second = v;\n            }\n        }\n        return second == Integer.MAX_VALUE ? -1 : second;\n    }\n}\n";
