R["apx-m5-longestrun"] = "public class Solution {\n    public static int process(String s) {\n        int best = 0;\n        int cur = 0;\n        for (int i = 0; i < s.length(); i++) {\n            if (i > 0 && s.charAt(i) == s.charAt(i - 1)) {\n                cur++;\n            } else {\n                cur = 1;\n            }\n            if (cur > best) {\n                best = cur;\n            }\n        }\n        return best;\n    }\n}\n";
W["apx-m5-longestrun"] = "public class Solution {\n    // BUG: counts the total string length when any repeat exists\n    public static int process(String s) {\n        int best = 0;\n        boolean anyRepeat = false;\n        for (int i = 1; i < s.length(); i++) {\n            if (s.charAt(i) == s.charAt(i - 1)) {\n                anyRepeat = true;\n            }\n        }\n        if (anyRepeat) {\n            return s.length();\n        }\n        return s.length() > 0 ? 1 : 0;\n    }\n}\n";
R["apx-m5-rle"] = "public class Solution {\n    public static String process(String s) {\n        if (s.length() == 0) {\n            return \"\";\n        }\n        StringBuilder out = new StringBuilder();\n        int run = 1;\n        for (int i = 1; i <= s.length(); i++) {\n            if (i < s.length() && s.charAt(i) == s.charAt(i - 1)) {\n                run++;\n            } else {\n                out.append(s.charAt(i - 1)).append(run);\n                run = 1;\n            }\n        }\n        return out.toString();\n    }\n}\n";
W["apx-m5-rle"] = "public class Solution {\n    // BUG: never flushes the final run \u2014 output truncated\n    public static String process(String s) {\n        if (s.length() == 0) {\n            return \"\";\n        }\n        StringBuilder out = new StringBuilder();\n        int run = 1;\n        for (int i = 1; i < s.length(); i++) {\n            if (s.charAt(i) == s.charAt(i - 1)) {\n                run++;\n            } else {\n                out.append(s.charAt(i - 1)).append(run);\n                run = 1;\n            }\n        }\n        return out.toString();\n    }\n}\n";
R["apx-cp-m5-midpair"] = "public class Solution {\n    public static String process(String s) {\n        if (s.length() < 3) {\n            return s;\n        }\n        int start = (s.length() - 1) / 2;\n        return s.substring(start, start + 2);\n    }\n}\n";
W["apx-cp-m5-midpair"] = "public class Solution {\n    // BUG: n/2 grabs the right-hand pair on even lengths\n    public static String process(String s) {\n        if (s.length() < 3) {\n            return s;\n        }\n        int start = s.length() / 2;\n        return s.substring(start, start + 2);\n    }\n}\n";
R["apx-m6-secondmax"] = "public class Solution {\n    public static int process(int[] arr) {\n        if (arr.length < 2) {\n            return -1;\n        }\n        int max = arr[0];\n        for (int v : arr) {\n            if (v > max) {\n                max = v;\n            }\n        }\n        int second = Integer.MIN_VALUE;\n        for (int v : arr) {\n            if (v < max && v > second) {\n                second = v;\n            }\n        }\n        return second == Integer.MIN_VALUE ? -1 : second;\n    }\n}\n";
W["apx-m6-secondmax"] = "public class Solution {\n    // BUG: single-pass branch misses equal-to-max \u2014 counts duplicates of max as second\n    public static int process(int[] arr) {\n        if (arr.length < 2) {\n            return -1;\n        }\n        int max = Integer.MIN_VALUE;\n        int second = Integer.MIN_VALUE;\n        for (int v : arr) {\n            if (v > max) {\n                second = max;\n                max = v;\n            } else if (v > second) {\n                second = v;\n            }\n        }\n        return second == Integer.MIN_VALUE ? -1 : second;\n    }\n}\n";
R["apx-m6-rotate"] = "public class Solution {\n    public static void rotate(int[] arr, int k) {\n        int n = arr.length;\n        if (n == 0) {\n            return;\n        }\n        k = k % n;\n        int[] tmp = new int[n];\n        for (int i = 0; i < n; i++) {\n            tmp[(i + k) % n] = arr[i];\n        }\n        for (int i = 0; i < n; i++) {\n            arr[i] = tmp[i];\n        }\n    }\n}\n";
W["apx-m6-rotate"] = "public class Solution {\n    // BUG: rotates LEFT instead of right (tmp[(i - k + n) % n])\n    public static void rotate(int[] arr, int k) {\n        int n = arr.length;\n        if (n == 0) {\n            return;\n        }\n        k = k % n;\n        int[] tmp = new int[n];\n        for (int i = 0; i < n; i++) {\n            tmp[((i - k) % n + n) % n] = arr[i];\n        }\n        for (int i = 0; i < n; i++) {\n            arr[i] = tmp[i];\n        }\n    }\n}\n";
R["apx-m6-mode"] = "public class Solution {\n    public static int process(java.util.ArrayList<Integer> list) {\n        int bestVal = 0;\n        int bestCount = 0;\n        for (int i = 0; i < list.size(); i++) {\n            int v = list.get(i);\n            int cnt = 0;\n            for (int j = 0; j < list.size(); j++) {\n                if (list.get(j).equals(v)) {\n                    cnt++;\n                }\n            }\n            if (cnt > bestCount || (cnt == bestCount && v < bestVal)) {\n                bestCount = cnt;\n                bestVal = v;\n            }\n        }\n        return bestVal;\n    }\n}\n";
W["apx-m6-mode"] = "public class Solution {\n    // BUG: keeps the FIRST tied value instead of the smallest (ties by first occurrence)\n    public static int process(java.util.ArrayList<Integer> list) {\n        int bestVal = 0;\n        int bestCount = 0;\n        for (int i = 0; i < list.size(); i++) {\n            int v = list.get(i);\n            int cnt = 0;\n            for (int j = 0; j < list.size(); j++) {\n                if (list.get(j).equals(v)) {\n                    cnt++;\n                }\n            }\n            if (cnt > bestCount || (cnt == bestCount && list.indexOf(v) < list.indexOf(bestVal))) {\n                bestCount = cnt;\n                bestVal = v;\n            }\n        }\n        return bestVal;\n    }\n}\n";
R["apx-m6-dedup"] = "public class Solution {\n    public static int process(int[] arr) {\n        if (arr.length == 0) {\n            return 0;\n        }\n        int w = 1;\n        for (int i = 1; i < arr.length; i++) {\n            if (arr[i] != arr[w - 1]) {\n                arr[w] = arr[i];\n                w++;\n            }\n        }\n        return w;\n    }\n}\n";
W["apx-m6-dedup"] = "public class Solution {\n    // BUG: off-by-one return \u2014 claims one extra element, exposing a garbage cell\n    public static int process(int[] arr) {\n        if (arr.length == 0) {\n            return 0;\n        }\n        int w = 1;\n        for (int i = 1; i < arr.length; i++) {\n            if (arr[i] != arr[w - 1]) {\n                arr[w] = arr[i];\n                w++;\n            }\n        }\n        return w + 1;\n    }\n}\n";
R["apx-m6-removefailing"] = "public class Solution {\n    public static int process(java.util.ArrayList<Integer> list) {\n        int removed = 0;\n        for (int i = list.size() - 1; i >= 0; i--) {\n            if (list.get(i) < 60) {\n                list.remove(i);\n                removed++;\n            }\n        }\n        return removed;\n    }\n}\n";
W["apx-m6-removefailing"] = "public class Solution {\n    // BUG: forgets to count \u2014 removes correctly but returns 0\n    public static int process(java.util.ArrayList<Integer> list) {\n        for (int i = list.size() - 1; i >= 0; i--) {\n            if (list.get(i) < 60) {\n                list.remove(i);\n            }\n        }\n        return 0;\n    }\n}\n";
R["apx-m6-interleave"] = "public class Solution {\n    public static int[] interleave(int[] a, int[] b) {\n        int[] out = new int[a.length + b.length];\n        int oi = 0;\n        int ai = 0;\n        int bi = 0;\n        while (ai < a.length || bi < b.length) {\n            if (ai < a.length) {\n                out[oi] = a[ai];\n                oi++;\n                ai++;\n            }\n            if (bi < b.length) {\n                out[oi] = b[bi];\n                oi++;\n                bi++;\n            }\n        }\n        return out;\n    }\n}\n";
W["apx-m6-interleave"] = "public class Solution {\n    // BUG: stops when the SHORTER list ends \u2014 drops the drain phase\n    public static int[] interleave(int[] a, int[] b) {\n        int[] out = new int[a.length + b.length];\n        int oi = 0;\n        for (int i = 0; i < Math.min(a.length, b.length); i++) {\n            out[oi] = a[i];\n            oi++;\n            out[oi] = b[i];\n            oi++;\n        }\n        return out;\n    }\n}\n";
R["apx-cp-m6-suffixsum"] = "public class Solution {\n    public static int process(int[] arr) {\n        int count = 0;\n        int suffix = 0;\n        for (int i = arr.length - 1; i >= 0; i--) {\n            if (arr[i] > suffix) {\n                count++;\n            }\n            suffix += arr[i];\n        }\n        return count;\n    }\n}\n";
W["apx-cp-m6-suffixsum"] = "public class Solution {\n    // BUG: adds arr[i] to the suffix BEFORE comparing \u2014 off-by-one state\n    public static int process(int[] arr) {\n        int count = 0;\n        int suffix = 0;\n        for (int i = arr.length - 1; i >= 0; i--) {\n            suffix += arr[i];\n            if (arr[i] > suffix) {\n                count++;\n            }\n        }\n        return count;\n    }\n}\n";
R["apx-m7-rotate"] = "public class Solution {\n    public static int[][] process(int[][] g) {\n        int rows = g.length;\n        int cols = g[0].length;\n        int[][] out = new int[cols][rows];\n        for (int r = 0; r < rows; r++) {\n            for (int c = 0; c < cols; c++) {\n                out[c][rows - 1 - r] = g[r][c];\n            }\n        }\n        return out;\n    }\n}\n";
W["apx-m7-rotate"] = "public class Solution {\n    // BUG: counter-clockwise rotation \u2014 wrong index on the new row\n    public static int[][] process(int[][] g) {\n        int rows = g.length;\n        int cols = g[0].length;\n        int[][] out = new int[cols][rows];\n        for (int r = 0; r < rows; r++) {\n            for (int c = 0; c < cols; c++) {\n                out[cols - 1 - c][r] = g[r][c];\n            }\n        }\n        return out;\n    }\n}\n";
R["apx-m7-neighborsum"] = "public class Solution {\n    public static int process(int[][] g, int r, int c) {\n        int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};\n        int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};\n        int sum = 0;\n        for (int d = 0; d < 8; d++) {\n            int nr = r + dr[d];\n            int nc = c + dc[d];\n            if (nr >= 0 && nr < g.length && nc >= 0 && nc < g[0].length) {\n                sum += g[nr][nc];\n            }\n        }\n        return sum;\n    }\n}\n";
W["apx-m7-neighborsum"] = "public class Solution {\n    // BUG: includes the cell itself \u2014 self counts as a neighbor\n    public static int process(int[][] g, int r, int c) {\n        int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};\n        int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};\n        int sum = 0;\n        for (int d = 0; d < 8; d++) {\n            int nr = r + dr[d];\n            int nc = c + dc[d];\n            if (nr >= 0 && nr < g.length && nc >= 0 && nc < g[0].length) {\n                sum += g[nr][nc];\n            }\n        }\n        return sum + g[r][c];\n    }\n}\n";
R["apx-m7-peaks"] = "public class Solution {\n    public static int process(int[][] g) {\n        int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};\n        int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};\n        int count = 0;\n        for (int r = 0; r < g.length; r++) {\n            for (int c = 0; c < g[0].length; c++) {\n                int sum = 0;\n                int cnt = 0;\n                for (int d = 0; d < 8; d++) {\n                    int nr = r + dr[d];\n                    int nc = c + dc[d];\n                    if (nr >= 0 && nr < g.length && nc >= 0 && nc < g[0].length) {\n                        sum += g[nr][nc];\n                        cnt++;\n                    }\n                }\n                if (g[r][c] * cnt > sum) {\n                    count++;\n                }\n            }\n        }\n        return count;\n    }\n}\n";
W["apx-m7-peaks"] = "public class Solution {\n    // BUG: divides by 8 always \u2014 corners and edges misjudged\n    public static int process(int[][] g) {\n        int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};\n        int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};\n        int count = 0;\n        for (int r = 0; r < g.length; r++) {\n            for (int c = 0; c < g[0].length; c++) {\n                int sum = 0;\n                for (int d = 0; d < 8; d++) {\n                    int nr = r + dr[d];\n                    int nc = c + dc[d];\n                    if (nr >= 0 && nr < g.length && nc >= 0 && nc < g[0].length) {\n                        sum += g[nr][nc];\n                    }\n                }\n                if (g[r][c] * 8 > sum) {\n                    count++;\n                }\n            }\n        }\n        return count;\n    }\n}\n";
R["apx-m7-ledger"] = "public class Solution {\n    public static int process(int[][] g) {\n        int total = 0;\n        for (int c = 0; c < g[0].length; c++) {\n            int col = 0;\n            for (int r = 0; r < g.length; r++) {\n                col += g[r][c];\n            }\n            total += Math.abs(col);\n        }\n        return total;\n    }\n}\n";
W["apx-m7-ledger"] = "public class Solution {\n    // BUG: sums absolute VALUES per cell instead of per column balance\n    public static int process(int[][] g) {\n        int total = 0;\n        for (int c = 0; c < g[0].length; c++) {\n            for (int r = 0; r < g.length; r++) {\n                total += Math.abs(g[r][c]);\n            }\n        }\n        return total;\n    }\n}\n";
R["apx-m7-spiral"] = "public class Solution {\n    public static int[][] fill(int rows, int cols) {\n        int[][] g = new int[rows][cols];\n        int v = 1;\n        int top = 0;\n        int bottom = rows - 1;\n        int left = 0;\n        int right = cols - 1;\n        while (top <= bottom && left <= right) {\n            for (int c = left; c <= right; c++) {\n                g[top][c] = v;\n                v++;\n            }\n            top++;\n            for (int r = top; r <= bottom; r++) {\n                g[r][right] = v;\n                v++;\n            }\n            right--;\n            if (top <= bottom) {\n                for (int c = right; c >= left; c--) {\n                    g[bottom][c] = v;\n                    v++;\n                }\n                bottom--;\n            }\n            if (left <= right) {\n                for (int r = bottom; r >= top; r--) {\n                    g[r][left] = v;\n                    v++;\n                }\n                left++;\n            }\n        }\n        return g;\n    }\n}\n";
W["apx-m7-spiral"] = "public class Solution {\n    // BUG: missing the re-check before the bottom row \u2014 single-column grids double-count\n    public static int[][] fill(int rows, int cols) {\n        int[][] g = new int[rows][cols];\n        int v = 1;\n        int top = 0;\n        int bottom = rows - 1;\n        int left = 0;\n        int right = cols - 1;\n        while (top <= bottom && left <= right) {\n            for (int c = left; c <= right; c++) {\n                g[top][c] = v;\n                v++;\n            }\n            top++;\n            for (int r = top; r <= bottom; r++) {\n                g[r][right] = v;\n                v++;\n            }\n            right--;\n            for (int c = right; c >= left; c--) {\n                g[bottom][c] = v;\n                v++;\n            }\n            bottom--;\n            if (left <= right) {\n                for (int r = bottom; r >= top; r--) {\n                    g[r][left] = v;\n                    v++;\n                }\n                left++;\n            }\n        }\n        return g;\n    }\n}\n";
R["apx-cp-m7-symmetric"] = "public class Solution {\n    public static boolean process(int[][] g) {\n        for (int r = 0; r < g.length; r++) {\n            for (int c = r + 1; c < g.length; c++) {\n                if (g[r][c] != g[c][r]) {\n                    return false;\n                }\n            }\n        }\n        return true;\n    }\n}\n";
W["apx-cp-m7-symmetric"] = "public class Solution {\n    // BUG: compares against the wrong mirror index (c - r instead of c, r)\n    public static boolean process(int[][] g) {\n        for (int r = 0; r < g.length; r++) {\n            for (int c = r + 1; c < g.length; c++) {\n                if (g[r][c] != g[c - r][r]) {\n                    return false;\n                }\n            }\n        }\n        return true;\n    }\n}\n";
R["apx-m8-parking"] = "public class Solution {\n    public static class Parking {\n        private int capacity;\n        private java.util.ArrayList<String> plates = new java.util.ArrayList<String>();\n\n        public Parking(int capacity) {\n            this.capacity = capacity;\n        }\n\n        public boolean arrive(String plate) {\n            if (plates.size() >= capacity) {\n                return false;\n            }\n            plates.add(plate);\n            return true;\n        }\n\n        public boolean depart(String plate) {\n            return plates.remove(plate);\n        }\n\n        public int count() {\n            return plates.size();\n        }\n    }\n}\n";
W["apx-m8-parking"] = "public class Solution {\n    public static class Parking {\n        private int capacity;\n        private java.util.ArrayList<String> plates = new java.util.ArrayList<String>();\n\n        public Parking(int capacity) {\n            this.capacity = capacity;\n        }\n\n        public boolean arrive(String plate) {\n            if (plates.size() >= capacity) {\n                return false;\n            }\n            plates.add(plate);\n            return true;\n        }\n\n        public boolean depart(String plate) {\n            // BUG: removes by INDEX semantics confusion \u2014 removes first element instead\n            if (plates.size() > 0) {\n                plates.remove(0);\n                return true;\n            }\n            return false;\n        }\n\n        public int count() {\n            return plates.size();\n        }\n    }\n}\n";
R["apx-m8-register"] = "public class Solution {\n    public static class Register {\n        private int owed;\n        private int paid;\n\n        public Register() {\n            owed = 0;\n            paid = 0;\n        }\n\n        public void scan(int price) {\n            owed += price;\n        }\n\n        public void pay(int cash) {\n            paid += cash;\n        }\n\n        public int changeDue() {\n            return Math.max(0, paid - owed);\n        }\n    }\n}\n";
W["apx-m8-register"] = "public class Solution {\n    public static class Register {\n        private int owed;\n        private int paid;\n\n        public Register() {\n            owed = 0;\n            paid = 0;\n        }\n\n        public void scan(int price) {\n            owed += price;\n        }\n\n        public void pay(int cash) {\n            paid += cash;\n        }\n\n        public int changeDue() {\n            // BUG: forgets the clamp \u2014 returns negative while owing\n            return paid - owed;\n        }\n    }\n}\n";
R["apx-m8-scoreboard"] = "public class Solution {\n    public static class Scoreboard {\n        private String home;\n        private String away;\n        private int homeScore;\n        private int awayScore;\n        private int homeFouls;\n        private int awayFouls;\n\n        public Scoreboard(String home, String away) {\n            this.home = home;\n            this.away = away;\n        }\n\n        public void score(String team, int points) {\n            if (team.equals(home)) {\n                homeScore += points;\n            } else if (team.equals(away)) {\n                awayScore += points;\n            }\n        }\n\n        public void foul(String team) {\n            if (team.equals(home)) {\n                homeFouls++;\n                if (homeFouls == 5) {\n                    awayScore += 2;\n                }\n            } else if (team.equals(away)) {\n                awayFouls++;\n                if (awayFouls == 5) {\n                    homeScore += 2;\n                }\n            }\n        }\n\n        public String leader() {\n            if (awayScore > homeScore) {\n                return away;\n            }\n            return home;\n        }\n    }\n}\n";
W["apx-m8-scoreboard"] = "public class Solution {\n    public static class Scoreboard {\n        private String home;\n        private String away;\n        private int homeScore;\n        private int awayScore;\n        private int homeFouls;\n        private int awayFouls;\n\n        public Scoreboard(String home, String away) {\n            this.home = home;\n            this.away = away;\n        }\n\n        public void score(String team, int points) {\n            if (team.equals(home)) {\n                homeScore += points;\n            } else if (team.equals(away)) {\n                awayScore += points;\n            }\n        }\n\n        public void foul(String team) {\n            // BUG: awards the bonus to the FOULING team instead of the opponent\n            if (team.equals(home)) {\n                homeFouls++;\n                if (homeFouls == 5) {\n                    homeScore += 2;\n                }\n            } else if (team.equals(away)) {\n                awayFouls++;\n                if (awayFouls == 5) {\n                    awayScore += 2;\n                }\n            }\n        }\n\n        public String leader() {\n            if (awayScore > homeScore) {\n                return away;\n            }\n            return home;\n        }\n    }\n}\n";
R["apx-cp-m8-locker"] = "public class Solution {\n    public static class Locker {\n        private String[] slots;\n\n        public Locker(int size) {\n            slots = new String[size];\n        }\n\n        public int claim(String name) {\n            for (int i = 0; i < slots.length; i++) {\n                if (slots[i] == null) {\n                    slots[i] = name;\n                    return i + 1;\n                }\n            }\n            return -1;\n        }\n\n        public void release(int num) {\n            if (num >= 1 && num <= slots.length) {\n                slots[num - 1] = null;\n            }\n        }\n\n        public String owner(int num) {\n            if (num >= 1 && num <= slots.length) {\n                return slots[num - 1];\n            }\n            return null;\n        }\n    }\n}\n";
W["apx-cp-m8-locker"] = "public class Solution {\n    public static class Locker {\n        private String[] slots;\n        private int next;\n\n        public Locker(int size) {\n            slots = new String[size];\n            next = 0;\n        }\n\n        public int claim(String name) {\n            // BUG: never reuses freed slots \u2014 always bumps next\n            if (next >= slots.length) {\n                return -1;\n            }\n            slots[next] = name;\n            next++;\n            return next;\n        }\n\n        public void release(int num) {\n            if (num >= 1 && num <= slots.length) {\n                slots[num - 1] = null;\n            }\n        }\n\n        public String owner(int num) {\n            if (num >= 1 && num <= slots.length) {\n                return slots[num - 1];\n            }\n            return null;\n        }\n    }\n}\n";
R["apx-m9-payroll"] = "public class Solution {\n    public static class Employee {\n        private String name;\n        private int base;\n\n        public Employee(String name, int base) {\n            this.name = name;\n            this.base = base;\n        }\n\n        public int pay() {\n            return base;\n        }\n    }\n\n    public static class Manager extends Employee {\n        private int bonus;\n\n        public Manager(String name, int base, int bonus) {\n            super(name, base);\n            this.bonus = bonus;\n        }\n\n        public int pay() {\n            return super.pay() + bonus;\n        }\n    }\n\n    public static int payroll(java.util.ArrayList<Employee> staff) {\n        int total = 0;\n        for (Employee e : staff) {\n            total += e.pay();\n        }\n        return total;\n    }\n}\n";
W["apx-m9-payroll"] = "public class Solution {\n    public static class Employee {\n        private String name;\n        private int base;\n\n        public Employee(String name, int base) {\n            this.name = name;\n            this.base = base;\n        }\n\n        public int pay() {\n            return base;\n        }\n    }\n\n    public static class Manager extends Employee {\n        private int bonus;\n\n        public Manager(String name, int base, int bonus) {\n            super(name, base);\n            this.bonus = bonus;\n        }\n\n        public int pay() {\n            // BUG: forgot super \u2014 calls itself forever (StackOverflowError)\n            return pay() + bonus;\n        }\n    }\n\n    public static int payroll(java.util.ArrayList<Employee> staff) {\n        int total = 0;\n        for (Employee e : staff) {\n            total += e.pay();\n        }\n        return total;\n    }\n}\n";
