R["apx-m11-altitude"] = "public class Solution {\n    public static int process(java.util.ArrayList<String> log) {\n        int altitude = 0;\n        for (String s : log) {\n            for (int i = 0; i < s.length(); i++) {\n                char ch = s.charAt(i);\n                if (ch == 'U') {\n                    altitude++;\n                } else if (ch == 'D') {\n                    altitude--;\n                }\n            }\n        }\n        return altitude;\n    }\n}\n";
W["apx-m11-altitude"] = "public class Solution {\n    // BUG: resets the accumulator for every string \u2014 loses earlier entries\n    public static int process(java.util.ArrayList<String> log) {\n        int total = 0;\n        for (String s : log) {\n            int altitude = 0;\n            for (int i = 0; i < s.length(); i++) {\n                char ch = s.charAt(i);\n                if (ch == 'U') {\n                    altitude++;\n                } else if (ch == 'D') {\n                    altitude--;\n                }\n            }\n            total = altitude;\n        }\n        return total;\n    }\n}\n";
R["apx-m11-dominant"] = "public class Solution {\n    public static int process(java.util.ArrayList<int[]> rows) {\n        int count = 0;\n        for (int[] row : rows) {\n            int max = Integer.MIN_VALUE;\n            int total = 0;\n            for (int v : row) {\n                total += v;\n                if (v > max) {\n                    max = v;\n                }\n            }\n            if (max > total - max) {\n                count++;\n            }\n        }\n        return count;\n    }\n}\n";
