R["apx-m14-song"] = "public class Solution {\n    public static class Song {\n        private String title;\n        private int plays;\n        private boolean liked;\n\n        public Song(String title) {\n            this.title = title;\n            plays = 0;\n            liked = false;\n        }\n\n        public void play() {\n            plays++;\n            if (plays == 5 && !liked) {\n                liked = true;\n            }\n        }\n\n        public void unlike() {\n            liked = false;\n        }\n\n        public boolean isLiked() {\n            return liked;\n        }\n    }\n}\n";
