R["apx-m6-secondmax"] = "public class Solution {\n    public static int process(int[] arr) {\n        if (arr.length < 2) {\n            return -1;\n        }\n        int max = arr[0];\n        for (int v : arr) {\n            if (v > max) {\n                max = v;\n            }\n        }\n        int second = Integer.MIN_VALUE;\n        for (int v : arr) {\n            if (v < max && v > second) {\n                second = v;\n            }\n        }\n        return second == Integer.MIN_VALUE ? -1 : second;\n    }\n}\n";
