R["apx-m8-scoreboard"] = "public class Solution {\n    public static class Scoreboard {\n        private String home;\n        private String away;\n        private int homeScore;\n        private int awayScore;\n        private int homeFouls;\n        private int awayFouls;\n\n        public Scoreboard(String home, String away) {\n            this.home = home;\n            this.away = away;\n        }\n\n        public void score(String team, int points) {\n            if (team.equals(home)) {\n                homeScore += points;\n            } else if (team.equals(away)) {\n                awayScore += points;\n            }\n        }\n\n        public void foul(String team) {\n            if (team.equals(home)) {\n                homeFouls++;\n                if (homeFouls == 5) {\n                    awayScore += 2;\n                }\n            } else if (team.equals(away)) {\n                awayFouls++;\n                if (awayFouls == 5) {\n                    homeScore += 2;\n                }\n            }\n        }\n\n        public String leader() {\n            if (awayScore > homeScore) {\n                return away;\n            }\n            return home;\n        }\n    }\n}\n";
W["apx-m8-scoreboard"] = "public class Solution {\n    public static class Scoreboard {\n        private String home;\n        private String away;\n        private int homeScore;\n        private int awayScore;\n        private int homeFouls;\n        private int awayFouls;\n\n        public Scoreboard(String home, String away) {\n            this.home = home;\n            this.away = away;\n        }\n\n        public void score(String team, int points) {\n            if (team.equals(home)) {\n                homeScore += points;\n            } else if (team.equals(away)) {\n                awayScore += points;\n            }\n        }\n\n        public void foul(String team) {\n            // BUG: awards the bonus to the FOULING team instead of the opponent\n            if (team.equals(home)) {\n                homeFouls++;\n                if (homeFouls == 5) {\n                    homeScore += 2;\n                }\n            } else if (team.equals(away)) {\n                awayFouls++;\n                if (awayFouls == 5) {\n                    awayScore += 2;\n                }\n            }\n        }\n\n        public String leader() {\n            if (awayScore > homeScore) {\n                return away;\n            }\n            return home;\n        }\n    }\n}\n";
R["apx-cp-m8-locker"] = "public class Solution {\n    public static class Locker {\n        private String[] slots;\n\n        public Locker(int size) {\n            slots = new String[size];\n        }\n\n        public int claim(String name) {\n            for (int i = 0; i < slots.length; i++) {\n                if (slots[i] == null) {\n                    slots[i] = name;\n                    return i + 1;\n                }\n            }\n            return -1;\n        }\n\n        public void release(int num) {\n            if (num >= 1 && num <= slots.length) {\n                slots[num - 1] = null;\n            }\n        }\n\n        public String owner(int num) {\n            if (num >= 1 && num <= slots.length) {\n                return slots[num - 1];\n            }\n            return null;\n        }\n    }\n}\n";
W["apx-cp-m8-locker"] = "public class Solution {\n    public static class Locker {\n        private String[] slots;\n        private int next;\n\n        public Locker(int size) {\n            slots = new String[size];\n            next = 0;\n        }\n\n        public int claim(String name) {\n            // BUG: never reuses freed slots \u2014 always bumps next\n            if (next >= slots.length) {\n                return -1;\n            }\n            slots[next] = name;\n            next++;\n            return next;\n        }\n\n        public void release(int num) {\n            if (num >= 1 && num <= slots.length) {\n                slots[num - 1] = null;\n            }\n        }\n\n        public String owner(int num) {\n            if (num >= 1 && num <= slots.length) {\n                return slots[num - 1];\n            }\n            return null;\n        }\n    }\n}\n";
R["apx-m9-payroll"] = "public class Solution {\n    public static class Employee {\n        private String name;\n        private int base;\n\n        public Employee(String name, int base) {\n            this.name = name;\n            this.base = base;\n        }\n\n        public int pay() {\n            return base;\n        }\n    }\n\n    public static class Manager extends Employee {\n        private int bonus;\n\n        public Manager(String name, int base, int bonus) {\n            super(name, base);\n            this.bonus = bonus;\n        }\n\n        public int pay() {\n            return super.pay() + bonus;\n        }\n    }\n\n    public static int payroll(java.util.ArrayList<Employee> staff) {\n        int total = 0;\n        for (Employee e : staff) {\n            total += e.pay();\n        }\n        return total;\n    }\n}\n";
W["apx-m9-payroll"] = "public class Solution {\n    public static class Employee {\n        private String name;\n        private int base;\n\n        public Employee(String name, int base) {\n            this.name = name;\n            this.base = base;\n        }\n\n        public int pay() {\n            return base;\n        }\n    }\n\n    public static class Manager extends Employee {\n        private int bonus;\n\n        public Manager(String name, int base, int bonus) {\n            super(name, base);\n            this.bonus = bonus;\n        }\n\n        public int pay() {\n            // BUG: forgot super \u2014 calls itself forever (StackOverflowError)\n            return pay() + bonus;\n        }\n    }\n\n    public static int payroll(java.util.ArrayList<Employee> staff) {\n        int total = 0;\n        for (Employee e : staff) {\n            total += e.pay();\n        }\n        return total;\n    }\n}\n";
R["apx-m9-shapes"] = "public class Solution {\n    public static abstract class Shape {\n        public abstract int area();\n\n        public String describe() {\n            return \"shape:\" + area();\n        }\n    }\n\n    public static class Square extends Shape {\n        private int side;\n\n        public Square(int side) {\n            this.side = side;\n        }\n\n        public int area() {\n            return side * side;\n        }\n    }\n\n    public static class Rect extends Shape {\n        private int w;\n        private int h;\n\n        public Rect(int w, int h) {\n            this.w = w;\n            this.h = h;\n        }\n\n        public int area() {\n            return w * h;\n        }\n    }\n\n    public static int totalArea(java.util.ArrayList<Shape> shapes) {\n        int total = 0;\n        for (Shape s : shapes) {\n            total += s.area();\n        }\n        return total;\n    }\n}\n";
W["apx-m9-shapes"] = "public class Solution {\n    public static abstract class Shape {\n        public abstract int area();\n\n        public String describe() {\n            return \"shape:\" + area();\n        }\n    }\n\n    public static class Square extends Shape {\n        private int side;\n\n        public Square(int side) {\n            this.side = side;\n        }\n\n        public int area() {\n            return side * side;\n        }\n    }\n\n    public static class Rect extends Shape {\n        private int w;\n        private int h;\n\n        public Rect(int w, int h) {\n            this.w = w;\n            this.h = h;\n        }\n\n        public int area() {\n            // BUG: swapped operands \u2014 w + h instead of w * h\n            return w + h;\n        }\n    }\n\n    public static int totalArea(java.util.ArrayList<Shape> shapes) {\n        int total = 0;\n        for (Shape s : shapes) {\n            total += s.area();\n        }\n        return total;\n    }\n}\n";
