R["apx-m12-average"] = "public class Solution {\n    public static double averageForDay(String[] days, double[] temps, String day) {\n        double sum = 0.0;\n        int n = 0;\n        for (int i = 0; i < days.length; i++) {\n            if (days[i].equals(day)) {\n                sum += temps[i];\n                n++;\n            }\n        }\n        if (n == 0) {\n            return 0.0;\n        }\n        return sum / n;\n    }\n}\n";
