R["apx-m14-candy"] = "public class Solution {\n    public static class CandyMachine {\n        private int coins;\n        private int candies;\n\n        public CandyMachine(int candies) {\n            this.candies = candies;\n            coins = 0;\n        }\n\n        public boolean buy() {\n            if (candies == 0) {\n                return false;\n            }\n            candies--;\n            coins++;\n            return true;\n        }\n\n        public void restock(int n) {\n            candies += n;\n        }\n\n        public int emptyCoins() {\n            int collected = coins;\n            coins = 0;\n            return collected;\n        }\n    }\n}\n";
