R["apx-m14-library"] = "public class Solution {\n    public static class Library {\n        private java.util.ArrayList<Song> songs = new java.util.ArrayList<Song>();\n\n        public void add(Song s) {\n            songs.add(s);\n        }\n\n        public void playAll() {\n            for (Song s : songs) {\n                s.play();\n            }\n        }\n\n        public int likedCount() {\n            int count = 0;\n            for (Song s : songs) {\n                if (s.isLiked()) {\n                    count++;\n                }\n            }\n            return count;\n        }\n    }\n\n    public static class Song {\n        private String title;\n        private int plays;\n        private boolean liked;\n\n        public Song(String title) {\n            this.title = title;\n            plays = 0;\n            liked = false;\n        }\n\n        public void play() {\n            plays++;\n            if (plays == 5) {\n                liked = true;\n            }\n        }\n\n        public void unlike() {\n            liked = false;\n        }\n\n        public boolean isLiked() {\n            return liked;\n        }\n    }\n}\n";
W["apx-m14-library"] = "public class Solution {\n    public static class Library {\n        private java.util.ArrayList<Song> songs = new java.util.ArrayList<Song>();\n        private int playTotal = 0;\n\n        public void add(Song s) {\n            songs.add(s);\n        }\n\n        public void playAll() {\n            for (Song s : songs) {\n                s.play();\n                playTotal++;\n            }\n        }\n\n        public int likedCount() {\n            // BUG: derives likes from the holder's own play counter\n            return playTotal / 5;\n        }\n    }\n\n    public static class Song {\n        private String title;\n        private int plays;\n        private boolean liked;\n\n        public Song(String title) {\n            this.title = title;\n            plays = 0;\n            liked = false;\n        }\n\n        public void play() {\n            plays++;\n            if (plays == 5) {\n                liked = true;\n            }\n        }\n\n        public void unlike() {\n            liked = false;\n        }\n\n        public boolean isLiked() {\n            return liked;\n        }\n    }\n}\n";
R["apx-cp-m14-player"] = "public class Solution {\n    public static class Player {\n        private int hp;\n        private int x;\n\n        public Player(int hp) {\n            this.hp = hp;\n            x = 0;\n        }\n\n        public void move(int steps) {\n            x += steps;\n        }\n\n        public void hit(int dmg) {\n            if (hp > 0) {\n                hp -= dmg;\n                if (hp < 0) {\n                    hp = 0;\n                }\n            }\n        }\n\n        public void heal(int amount) {\n            if (hp > 0) {\n                hp += amount;\n            }\n        }\n\n        public int getHp() {\n            return hp;\n        }\n\n        public int getX() {\n            return x;\n        }\n    }\n}\n";
